    int32_t head[ kBuckets ];
    int32_t count;
    bool overflow;
    // THE MESSAGE FORM'S SLOTS (docs/SPEC-TABLES.md §3.3). A form 2 wire
    // names ids through the CONNECTION's table, which is the unit's whole
