// table RangedSigned — TABLE-wire storage: relocatable, bounded, defaults in the
// member initializers (docs/SPEC-TABLES.md)
struct RangedSigned {
    int8_t i8_span = 0;
    int8_t i8_low = 0;
    int8_t i8_high = 0;
    int8_t i8_inside = 0;
    int16_t i16_span = 0;
    int16_t i16_low = 0;
    int16_t i16_high = 0;
    int16_t i16_inside = 0;
    int32_t i32_span = 0;
    int32_t i32_low = 0;
    int32_t i32_high = 0;
    int32_t i32_inside = 0;
    int64_t i64_span = 0;
    int64_t i64_low = 0;
    int64_t i64_high = 0;
    int64_t i64_inside = 0;
    int16_t edges[4] = {}; // used count beside it; count in [0, 4]
    int32_t edges_count = 0;
};

// table RangedUnsigned — TABLE-wire storage: relocatable, bounded, defaults in the
// member initializers (docs/SPEC-TABLES.md)
struct RangedUnsigned {
    uint8_t u8_span = 0;
    uint8_t u8_low = 0;
    uint8_t u8_high = 1;
    uint8_t u8_inside = 1;
    uint16_t u16_span = 0;
    uint16_t u16_low = 0;
    uint16_t u16_high = 1;
    uint16_t u16_inside = 1;
    uint32_t u32_span = 0;
    uint32_t u32_low = 0;
    uint32_t u32_high = 1;
    uint32_t u32_inside = 1;
    uint64_t u64_span = 0;
    uint64_t u64_low = 0;
    uint64_t u64_high = 1ull;
    uint64_t u64_inside = 1ull;
    uint64_t counts[4] = {}; // used count beside it; count in [0, 4]
    int32_t counts_count = 0;
};

// table RangedWidths — TABLE-wire storage: relocatable, bounded, defaults in the
