    value.i8_low = 0;
    value.i8_high = 0;
    value.i8_inside = 0;
    value.i16_span = 0;
    value.i16_low = 0;
    value.i16_high = 0;
    value.i16_inside = 0;
    value.i32_span = 0;
    value.i32_low = 0;
    value.i32_high = 0;
    value.i32_inside = 0;
    value.i64_span = 0;
    value.i64_low = 0;
    value.i64_high = 0;
    value.i64_inside = 0;
    memset( value.edges, 0, sizeof( value.edges ) );
