// ---- relocatability, enforced: the wire is a pure length-prefixed
// stream AND the decoded storage is pointer-free — every closure type
// must stay trivially copyable and standard-layout, so instances can be
// memcpy'd, mmap'd, shared across processes, and walked through
// descriptor offsets. A failure here means a pointer, virtual or
// non-trivial member crept into generated storage.
//
// They ask the COMPILER ITSELF, which is what every C++ standard library
// answers the same two questions with — and it costs this header no
// include at all.
static_assert( __is_trivially_copyable( RangedSigned ), "RangedSigned must stay relocatable" );
static_assert( __is_standard_layout( RangedSigned ), "RangedSigned must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( RangedUnsigned ), "RangedUnsigned must stay relocatable" );
static_assert( __is_standard_layout( RangedUnsigned ), "RangedUnsigned must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( RangedWidths ), "RangedWidths must stay relocatable" );
static_assert( __is_standard_layout( RangedWidths ), "RangedWidths must stay standard-layout for offsetof" );

